113	/** Lists a client's invoices, opens one, starts new drafts and adds lines to them. */
114	@Service
115	public class InvoiceService {
116	
117	    /** A new invoice is due this many days after it is issued. */
118	    static final int PAYMENT_TERMS_DAYS = 30;
119	
120	    private final InvoiceRepository invoices;
121	    private final ClientRepository clients;
122	    private final Today today;
123	
124	    public InvoiceService(InvoiceRepository invoices, ClientRepository clients, Today today) {
125	        this.invoices = invoices;
126	        this.clients = clients;
127	        this.today = today;
128	    }
129	
130	    @Transactional(readOnly = true)
131	    public List<Invoice> forClient(Long clientId) {
132	        return invoices.findByClientIdOrderByIdAsc(clientId);
133	    }
134	
135	    @Transactional(readOnly = true)
136	    public Optional<Invoice> find(Long id) {
137	        return invoices.findWithLinesById(id);
138	    }
139	
140	    /** An empty draft for the client, issued today and due 30 days later; empty if no such client. */
141	    @Transactional
142	    public Optional<Invoice> newDraft(Long clientId) {
143	        if (!clients.existsById(clientId)) {
144	            return Optional.empty();
145	        }
146	        LocalDate issued = today.date();
147	        return Optional.of(invoices.save(Invoice.draft(clientId, issued, issued.plusDays(PAYMENT_TERMS_DAYS))));
148	    }
149	
150	    /**
151	     * Adds a line to a draft invoice; empty if no such invoice. The line has already been checked;
152	     * a sent invoice refuses it.
153	     */
154	    @Transactional
155	    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice) {
156	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
157	        found.ifPresent(invoice -> {
158	            if (!invoice.isDraft()) {
159	                throw new InvoiceRejectedException("Only a draft invoice can take new lines.");
160	            }
161	            invoice.addLine(new InvoiceLine(description, qty, unitPrice));
162	            invoices.saveAndFlush(invoice);
163	        });
164	        return found;
165	    }
166	}
